insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('fcdac3f1-ca44-4bce-a16b-8e07666447cf', '53e914fe-87af-462a-b836-9deeec047e81', $$figuur 1 — omzetting van fenylalanine tot kaneelzuur$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-pal-context1.png$$,
   $$PAL is een enzym dat voorkomt in planten en micro-organismen. PAL zet het aminozuur fenylalanine om tot kaneelzuur. figuur 1: onvolledige reactievergelijking van de omzetting van fenylalanine (H₂N-CH(CH₂-C₆H₅)-COOH) tot kaneelzuur (C₆H₅-CH=CH-COOH), met een tweede, nog onbekend reactieproduct.$$, 'inline'),
  ('f4cfb3af-8511-476d-a447-2f268370b179', '53e914fe-87af-462a-b836-9deeec047e81', $$figuur 2 — vorming van de MIO-groep uit ~Ala–Ser–Gly~$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-pal-context2.png$$,
   $$Uit onderzoek naar de structuur van PAL bleek dat in PAL een opvallende kenmerkende groep aanwezig is: de zogeheten MIO-groep. De MIO-groep wordt bij de synthese van PAL gevormd door ringsluiting van een deel van de eiwitketen dat kan worden weergegeven met ~Ala–Ser–Gly~. figuur 2: structuurformule van de gevormde MIO-groep (een vijfring met C=C-, C=N- en C=O-bindingen), ontstaan uit het tripeptidegedeelte ~Ala–Ser–Gly~. De eerste stap in de vorming van de MIO-groep is de sluiting van de vijfring door een additiereactie binnen het enzymmolecuul. In de reacties die leiden tot MIO worden twee watermoleculen afgesplitst. Hierbij wordt onder andere de C=C-binding gevormd.$$, 'inline'),
  ('58ade700-904a-4119-95cb-2a3a8e81ab3b', '53e914fe-87af-462a-b836-9deeec047e81', $$PAL-varianten met Phe110 of Tyr110$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-pal-context3.png$$,
   $$De onderzoekers vermoedden dat de MIO-groep een rol speelt in de omzetting van fenylalanine tot kaneelzuur. Om vast te stellen welke aminozuureenheden nog meer een rol spelen bij de omzetting, hebben ze rondom de MIO-groep veranderingen aangebracht in de aminozuursamenstelling van PAL. Wanneer op positie 110 het aminozuur Phe werd ingebouwd, bleek de gevormde PAL nauwelijks nog katalytische activiteit te vertonen. In actieve PAL is op plaats 110 de aminozuureenheid Tyr (Tyr110) aanwezig.$$, 'inline'),
  ('7ef6d1ad-8cbf-4aa1-b273-e0686dffb552', '53e914fe-87af-462a-b836-9deeec047e81', $$puntmutatie in het DNA dat codeert voor PAL$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-pal-context4.png$$,
   $$Om deze PAL-variant te kunnen produceren, hebben de onderzoekers in een micro-organisme een puntmutatie aangebracht in het deel van het DNA dat codeert voor PAL. Een puntmutatie is de vervanging van een basenpaar in het DNA door een ander basenpaar. De code voor het eerste aminozuur van PAL begint bij het basenpaar met nummer 1.$$, 'inline'),
  ('f6f3a32e-d8d1-4fb0-9937-178c66bc444b', '53e914fe-87af-462a-b836-9deeec047e81', $$fenylalanine bij pH = 8,80$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-pal-context5.png$$,
   $$Het pH-optimum van PAL ligt bij pH = 8,80. Bij deze pH komen moleculen fenylalanine vooral voor in de vorm zoals hiernaast is weergegeven. De Kz van de ~NH₃⁺-groep in fenylalanine bedraagt 7,4·10⁻¹⁰. Structuurformule: fenylalanine (pH = 8,80), met een fenylgroep aan een CH₂-groep, gebonden aan een centraal C-atoom met een geprotoneerde aminogroep (H-N⁺H₂-) aan de ene kant en een gedeprotoneerde carboxylgroep (-C(=O)-O⁻) aan de andere kant.$$, 'inline'),
  ('f0a4fafe-9a5b-4b46-a409-06978a6838bb', '53e914fe-87af-462a-b836-9deeec047e81', $$figuur 3 — oriëntatie van fenylalanine bij het actieve centrum$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-pal-context6.png$$,
   $$Nader onderzoek leidde uiteindelijk tot opheldering van de rol van de MIO-groep en van Tyr110 bij de omzetting van fenylalanine tot kaneelzuur. De volgende punten zijn vastgesteld: de MIO-groep bevindt zich in een holte van het enzym en katalyseert de omzetting van fenylalanine; de restgroep van Tyr110 bevindt zich bij de ingang van deze holte; bij het pH-optimum van PAL heeft de restgroep van Tyr110 een negatieve lading. In figuur 3 is schematisch weergegeven hoe volgens de onderzoekers een fenylalanine-deeltje het actieve centrum van een molecuul PAL nadert. figuur 3: schema met de MIO-groep in de holte van het enzym, de negatief geladen restgroep van Tyr110 bij de ingang, en een naderend fenylalanine-deeltje (met een CH₂-groep, een positief geladen ~NH₃⁺-groep en een negatief geladen carboxylaatgroep -COO⁻). Tyr110 oefent aantrekkende en afstotende krachten uit op atoomgroepen van een fenylalanine-deeltje. Door deze interacties wordt het fenylalanine-deeltje georiënteerd zoals in figuur 3 is weergegeven.$$, 'inline'),
  ('1b631491-fa6c-4eaf-9c4a-96e56ede7b0f', '53e914fe-87af-462a-b836-9deeec047e81', $$turnover frequency-bepaling van PAL$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-pal-context7.png$$,
   $$In een meting bleek een monster van 148 mg onzuivere PAL de vorming van 158 µmol kaneelzuur per minuut te katalyseren. Het monster bestond voor 90 massa% uit PAL. De overige 10 massa% bestond uit enzymen zonder katalytisch effect op de reactie. Met behulp van deze gegevens is het mogelijk de turnover frequency (TOF) te berekenen. De TOF is gedefinieerd als het aantal substraatmoleculen dat per minuut door één molecuul PAL kan worden omgezet.$$, 'inline'),
  ('f88fa8fd-e9b1-4c37-bafd-ef5556e8ffe6', '8db2ac27-404b-4a57-a618-2743bddb5d43', $$waterstof als autobrandstof vergeleken met benzine$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-waterstofopslag-in-carbazool-context1.png$$,
   $$Waterstof wordt pas een alternatief voor het gebruik van benzine als autobrandstof, wanneer waterstofauto's met een volle tank eenzelfde afstand kunnen afleggen als een gangbare benzineauto met een tank gevuld met 50 liter benzine. Uit metingen is gebleken dat een benzineauto voor het afleggen van eenzelfde afstand tweemaal zoveel chemische energie nodig heeft als een waterstofauto.$$, 'inline'),
  ('f4b46d3c-316f-4b6b-811f-5a28bcc553db', '8db2ac27-404b-4a57-a618-2743bddb5d43', $$N-ethylcarbazool als waterstofdrager$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-waterstofopslag-in-carbazool-context2.png$$,
   $$Waterstof als brandstof heeft als groot nadeel dat het onder hoge druk moet worden opgeslagen. Daarom wordt veel onderzoek gedaan naar manieren om waterstof chemisch te binden aan een drager. Recent onderzoek richt zich op N-ethylcarbazool als waterstofdrager. Structuurformule: N-ethylcarbazool, een tricyclische stof opgebouwd uit twee benzeenringen gefuseerd met een vijfring met een stikstofatoom, waaraan een ethylgroep (-CH₂-CH₃) hangt. N-ethylcarbazool bindt waterstof door additie. Alle dubbele bindingen in N-ethylcarbazool worden hierbij omgezet tot enkelvoudige bindingen. Het product wordt perhydro-N-ethylcarbazool genoemd. De massa neemt hierbij minder dan 10% toe.$$, 'inline'),
  ('f5b5e6f1-2272-4b6d-abb1-a7b092a258d0', '8db2ac27-404b-4a57-a618-2743bddb5d43', $$figuur 1 — concentratieverloop bij additie van waterstof aan N-ethylcarbazool$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-waterstofopslag-in-carbazool-context3.png$$,
   $$In een experiment is het verloop van de additie van waterstof aan N-ethylcarbazool onderzocht. Het bleek dat in de loop van het experiment enkele tussenproducten konden worden aangetoond. Van de beginstof en het eindproduct en van een aantal tussenproducten is het verloop van de concentraties gemeten. In figuur 1 zijn enkele resultaten van de metingen weergegeven. De schaal op de y-assen verschilt per diagram. Het volume van het reactiemengsel was gedurende het gehele experiment constant. figuur 1: zes diagrammen van [stof] (mol L⁻¹) tegen t (min, 0-430) voor: N-ethylcarbazool (daalt snel van 3,0·10⁻¹ naar 0), tussenproduct 1 (piekt snel en daalt naar 0), tussenproduct 2 (stijgt snel naar circa 4,0·10⁻³ en daalt geleidelijk), tussenproduct 3 (stijgt snel naar 6,0·10⁻² en daalt geleidelijk), tussenproduct 4 (stijgt geleidelijk en daalt weer) en perhydro-N-ethylcarbazool (stijgt geleidelijk naar 3,0·10⁻¹).$$, 'inline'),
  ('4729b8b6-505d-4039-bd6a-56e906526e5c', '8db2ac27-404b-4a57-a618-2743bddb5d43', $$waterstofvorming uit perhydro-N-ethylcarbazool$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-waterstofopslag-in-carbazool-context4.png$$,
   $$In de waterstofauto wordt het perhydro-N-ethylcarbazool in aanwezigheid van een katalysator verwarmd tot 200 °C. In een endotherme reactie wordt waterstof gevormd dat in de auto naar een brandstofcel wordt gevoerd. Zuivere waterstof is zeer explosiegevaarlijk. Door het gebruik van perhydro-N-ethylcarbazool als waterstofdrager wordt dit probleem voorkomen.$$, 'inline'),
  ('d14e32c7-6a42-4744-97a4-fe5f484be13f', '8db2ac27-404b-4a57-a618-2743bddb5d43', $$uitwerkbijlage vraag 14 — onvolledig energiediagram$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-waterstofopslag-in-carbazool-context5-uitwerkbijlage-vraag14.png$$,
   $$Onvolledig energiediagram met op de x-as het reactieverloop en op de y-as de energie; het niveau van perhydro-N-ethylcarbazool (beginstof) is gegeven, de niveaus van het overgangscomplex en van de reactieproducten (waterstof en N-ethylcarbazool) ontbreken nog.$$, 'uitwerkbijlage'),
  ('3c320be1-f4be-4a99-a8d1-ac249968f30e', '7cddafe7-58c1-4630-9bb6-791a00ce2761', $$4-hydroxystyreen en BOC-4-hydroxystyreen in copolymeer X$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-polymeren-maken-de-chip-context1.png$$,
   $$Een computerchip wordt gemaakt van een dunne plaat van puur silicium, een zogeheten wafer. Hierop worden patronen van afwisselend geleidende en niet-geleidende materialen aangebracht. Om deze patronen aan te brengen, maakt men gebruik van een fotogevoelig materiaal, waarvan de oplosbaarheid verandert onder invloed van uv-licht. Een veelgebruikt fotogevoelig materiaal bevat onder andere een copolymeer dat door additiepolymerisatie is ontstaan uit 4-hydroxystyreen en BOC-4-hydroxystyreen. Dit copolymeer noemen we in deze opgave copolymeer X. Structuurformules: 4-hydroxystyreen (HO-C₆H₄-CH=CH₂) en BOC-4-hydroxystyreen ((CH₃)₃C-O-C(=O)-O-C₆H₄-CH=CH₂). BOC-4-hydroxystyreen wordt gemaakt uit 4-hydroxystyreen en di-tert-butyldicarbonaat. Bij deze reactie ontstaan, behalve BOC-4-hydroxystyreen, ook methylpropaan-2-ol en één andere stof. Op de uitwerkbijlage vind je een onvolledige vergelijking voor deze reactie.$$, 'inline'),
  ('9610346d-1067-4a07-91c7-aea1fd0adeae', '7cddafe7-58c1-4630-9bb6-791a00ce2761', $$vorming van de fotogevoelige laag met PAG$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-polymeren-maken-de-chip-context2.png$$,
   $$Op de wafer wordt eerst een laag siliciumdioxide aangebracht. Daarop wordt een fotogevoelige laag aangebracht. De fotogevoelige laag bevat copolymeer X en een fotogevoelige stof, PAG. De fotogevoelige laag wordt met uv-licht in het gewenste patroon beschenen. Onder invloed van uv-licht vormt een molecuul PAG één H⁺-ion. De gevormde H⁺-ionen zitten niet vast op één plek, maar diffunderen langzaam door de fotogevoelige laag. De H⁺-ionen katalyseren de omzetting van de BOC-4-hydroxystyreen-eenheden uit copolymeer X tot 4-hydroxystyreen-eenheden, methylpropeen en koolstofdioxide.$$, 'inline'),
  ('91322406-7b27-4b53-b5e3-3b929fc13b8d', '7cddafe7-58c1-4630-9bb6-791a00ce2761', $$oplosbaarheidsverschil poly-4-hydroxystyreen en copolymeer X$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-polymeren-maken-de-chip-context3.png$$,
   $$Na het belichten zijn in de belichte delen alle BOC-4-hydroxystyreen-eenheden omgezet. Vervolgens wordt de wafer gespoeld met een oplosmiddel. Poly-4-hydroxystyreen en copolymeer X verschillen in hun oplosbaarheid. Ze lossen beide niet goed op in water. Maar poly-4-hydroxystyreen lost wel op in een basische oplossing en copolymeer X niet. Door te spoelen met een basische oplossing lossen alleen die delen van de fotogevoelige laag op die met uv-licht zijn beschenen. De oplosbaarheid van poly-4-hydroxystyreen in een basische oplossing is te verklaren met behulp van het gegeven dat de OH-groep van elke 4-hydroxystyreeneenheid in een basische oplossing een H⁺ afstaat.$$, 'inline'),
  ('ac552e6c-b116-4dd1-9360-7c827fbcc4b2', '7cddafe7-58c1-4630-9bb6-791a00ce2761', $$plasma-etsen van de SiO₂-laag met CF₄ en H₂$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-polymeren-maken-de-chip-context4.png$$,
   $$Nadat de wafer is ontwikkeld, wordt hij geëtst met een gasmengsel van CF₄ en H₂. Hierbij wordt de SiO₂-laag verwijderd op de plekken waar deze niet wordt beschermd door de fotogevoelige laag. Zo ontstaat het gewenste patroon in de SiO₂-laag. Onder de gebruikte omstandigheden valt een groot deel van de moleculen CF₄ en H₂ uiteen en worden radicalen en dubbelradicalen gevormd. Het mengsel dat zo ontstaat wordt een plasma genoemd. In dit plasma treden de volgende reacties op: CF₄ → CF₂•• + 2 F• (reactie 1); H₂ → 2 H• (reactie 2); H• + F• → HF (reactie 3). Dit plasma reageert vervolgens met SiO₂: SiO₂ (s) + 4 F• → SiF₄ (g) + 2 O•• (reactie 4); SiO₂ (s) + 2 CF₂•• → SiF₄ (g) + 2 CO (g) (reactie 5). Op plekken waar de SiO₂-laag weg gereageerd is, kan het plasma ook met het silicium reageren volgens: Si (s) + 4 F• → SiF₄ (g) (reactie 6). Het doel van het etsen is om uitsluitend de SiO₂-laag te verwijderen terwijl de Si-laag intact blijft. De concentratie H₂ in het plasmamengsel beïnvloedt zowel de snelheid waarmee SiO₂ wordt geëtst (de etssnelheid) als de mate waarin SiO₂ ten opzichte van Si wordt geëtst (de selectiviteit).$$, 'inline'),
  ('7522c76f-346e-4bdd-a7be-b6e043049fab', '7cddafe7-58c1-4630-9bb6-791a00ce2761', $$uitwerkbijlage vraag 15 — onvolledige vergelijking BOC-4-hydroxystyreen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-polymeren-maken-de-chip-context5-uitwerkbijlage-vraag15.png$$,
   $$Onvolledige reactievergelijking in structuurformules: 4-hydroxystyreen + di-tert-butyldicarbonaat → BOC-4-hydroxystyreen + .... + ....; het product BOC-4-hydroxystyreen is al gegeven, de twee overige reactieproducten (waaronder methylpropaan-2-ol) ontbreken nog.$$, 'uitwerkbijlage'),
  ('113c094e-df6b-49b9-a889-4160096e6d05', '80051cad-c69e-4c7d-a0b4-d8c8d287cd68', $$reactieve extractie van glutaminezuur met butaan-1-ol$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-chemicalien-uit-biomassa-context1.png$$,
   $$Chemicaliën die in de chemische industrie in grote hoeveelheden worden gebruikt (bulkchemicaliën) worden nu vaak gemaakt van aardolie. Om het gebruik van aardolie terug te dringen, wordt veel onderzoek gedaan om deze bulkchemicaliën te produceren op basis van biomassa. Glutaminezuur is in veel plantenafval het meest voorkomende aminozuur. In een onderzoek is gekeken of glutaminezuur uit plantenafval gewonnen kan worden met behulp van een zogenoemde reactieve extractie. Daartoe werden water en een overmaat butaan-1-ol toegevoegd aan een hoeveelheid gehydrolyseerd plantenafval. Butaan-1-ol lost slecht op in water en vormt een laag boven op het water. Het glutaminezuur vormt een di-ester met butaan-1-ol. De gevormde di-ester lost vervolgens op in de laag butaan-1-ol.$$, 'inline'),
  ('f4833de2-3c40-48ba-b5da-b26db0be9d83', '80051cad-c69e-4c7d-a0b4-d8c8d287cd68', $$vorming van aminozuuresters aan het grensvlak$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-chemicalien-uit-biomassa-context2.png$$,
   $$Behalve glutaminezuur reageren ook de andere aminozuren met butaan-1-ol tot esters. De vorming van deze esters treedt op aan het grensoppervlak van beide vloeistoffen. De omzetting verloopt sneller wanneer het reactiemengsel intensief wordt geroerd.$$, 'inline'),
  ('147d6155-edca-48ba-9131-1283ee2a2111', '80051cad-c69e-4c7d-a0b4-d8c8d287cd68', $$NVP als monomeer voor polyvinylpyrrolidon$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-chemicalien-uit-biomassa-context3.png$$,
   $$Na het afscheiden van de gevormde (di-)esters van aminozuren uit butaan-1-ol worden de esters gehydrolyseerd. Uit het onderzoek bleek dat het mogelijk is om op deze wijze uit plantenafval een mengsel van aminozuren te winnen met een hoog gehalte aan glutaminezuur. Een Nederlandse onderzoeker heeft in zijn proefschrift een vervolgonderzoek hierop gepubliceerd. Hij heeft onderzocht of uit het onzuivere glutaminezuur twee belangrijke bulkchemicaliën kunnen worden geproduceerd. Deze chemicaliën zijn N-vinylpyrrolidon (NVP) en N-methylpyrrolidon (NMP). NVP is het monomeer voor het veelgebruikte polymeer polyvinylpyrrolidon dat via additiepolymerisatie wordt gevormd uit NVP. Structuurformule: NVP, een vijfring (2-pyrrolidon-achtige ring) met een carbonylgroep (C=O) en een stikstofatoom waaraan een vinylgroep (-CH=CH₂) hangt.$$, 'inline'),
  ('7d5d9d23-4d8a-4536-8f3a-f0288a9246b4', '80051cad-c69e-4c7d-a0b4-d8c8d287cd68', $$oplosbaarheid van NMP — mesomere grensstructuur$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-chemicalien-uit-biomassa-context4.png$$,
   $$NMP is een oplosmiddel dat op grote schaal wordt gebruikt om koolwaterstoffen op te lossen. Het is ook goed oplosbaar in water. De oplosbaarheid van NMP in water is te verklaren met behulp van de Lewisstructuur van een mesomere grensstructuur van NMP. In deze Lewisstructuur komen formele ladingen voor. Structuurformule: NMP, een vijfring (pyrrolidon) met een carbonylgroep (C=O) en een stikstofatoom waaraan een methylgroep (-CH₃) hangt.$$, 'inline'),
  ('c07756ac-cb59-45ee-9824-a626d5d8f59b', '80051cad-c69e-4c7d-a0b4-d8c8d287cd68', $$figuur 1 — routes van glutaminezuur naar NMP en NVP$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-chemicalien-uit-biomassa-context5.png$$,
   $$In figuur 1 zijn de routes weergegeven die de onderzoeker voorstelt om glutaminezuur uit het mengsel van aminozuren om te zetten tot NMP en NVP. In figuur 1 is een aantal structuurformules schematisch weergegeven. figuur 1: glutaminezuur (in een mengsel met o.a. glutaminezuur) reageert in reactie 1 onder afsplitsing van CO₂ tot GABA; GABA reageert in reactie 2 onder afsplitsing van H₂O tot 2-pyrrolidon; 2-pyrrolidon reageert in reactie 3 met CH₃OH onder vorming van H₂O tot NMP; 2-pyrrolidon reageert in reactie 4 met ethyn tot NVP. In reactie 1 uit figuur 1 wordt het onzuivere glutaminezuur omgezet tot de stof GABA en CO₂. In een scheidingsruimte wordt GABA gescheiden van het afval, waarin onder andere ongereageerde aminozuren aanwezig zijn. In reactie 2 treedt ringsluiting van GABA op waarbij water ontstaat.$$, 'inline'),
  ('acfab074-5740-432e-a64b-41b16a062c70', '80051cad-c69e-4c7d-a0b4-d8c8d287cd68', $$vorming van NVP uit 2-pyrrolidon en ethyn$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-chemicalien-uit-biomassa-context6.png$$,
   $$In reactie 2 ontstaat 2-pyrrolidon, de grondstof voor zowel NMP als NVP. Voor de productie van NVP laat men in reactie 4 het 2-pyrrolidon reageren met ethyn.$$, 'inline'),
  ('e7c1104c-7b8b-47e7-8a8e-b5b7907b0d30', '80051cad-c69e-4c7d-a0b4-d8c8d287cd68', $$industrieel productieproces van NMP en NVP$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-chemicalien-uit-biomassa-context7.png$$,
   $$De onderzoeker heeft de verschillende stappen voor de productie van NMP en NVP uit glutaminezuur onderzocht met behulp van laboratoriumreactoren. Op basis van de resultaten heeft hij een industrieel productieproces ontworpen. Dit proces kan worden weergegeven met een blokschema. Dit blokschema is op de uitwerkbijlage onvolledig weergegeven. Hieronder is het productieproces van NMP en NVP beschreven. 1: In reactor R1 wordt een mengsel van aminozuren ingevoerd. In R1 vindt reactie 1 uit figuur 1 plaats. Voor reactie 1 zijn zowel de omzetting als de selectiviteit 100%. 2: In scheidingsruimte S1 wordt het mengsel afkomstig uit R1 volledig gescheiden in GABA en afval van de ongereageerde aminozuren. 3: In R2 vindt reactie 2 plaats. Voor reactie 2 zijn zowel de omzetting als de selectiviteit 100%. 4: In R2 treedt ook reactie 3 op. Methanol is hier in overmaat aanwezig. Voor reactie 3 is de omzetting 50% en de selectiviteit 92%. 5: In S2 wordt het mengsel afkomstig uit R2 met behulp van destillatie gescheiden in vier stromen: NMP, 2-pyrrolidon, methanol en afval. De overmaat methanol kan voor 95% worden teruggevoerd naar R2. De overige 5% bevindt zich met onder andere water in het afval van S2. 6: Het 2-pyrrolidon dat in R2 niet heeft gereageerd wordt volledig doorgevoerd naar reactor R3. Hier treedt reactie 4 op. Voor reactie 4 is de omzetting 100% en de selectiviteit 90%. 7: In S3 wordt ten slotte het NVP gescheiden van een afvalstroom. De term omzetting geeft aan welk percentage van het aantal mol beginstof in een reactie is omgezet. De term selectiviteit geeft aan welk percentage van het aantal mol omgezette stof heeft gereageerd tot het gewenste product.$$, 'inline'),
  ('21929679-0e97-48af-bc44-9ed196d3be05', '80051cad-c69e-4c7d-a0b4-d8c8d287cd68', $$hoeveelheid glutaminezuur in de laboratoriumopzet$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-chemicalien-uit-biomassa-context8.png$$,
   $$De bovenstaande meetgegevens zijn verkregen in een laboratoriumopzet van de fabriek. De metingen zijn gedaan aan een mengsel van aminozuren waarin 1538 kg glutaminezuur aanwezig was.$$, 'inline'),
  ('7a3da6cf-085a-4d53-b1a7-1c2f407d46d7', '80051cad-c69e-4c7d-a0b4-d8c8d287cd68', $$uitwerkbijlage vraag 27 — onvolledig blokschema productieproces$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-chemicalien-uit-biomassa-context9-uitwerkbijlage-vraag27.png$$,
   $$Onvolledig blokschema van het productieproces: het mengsel met glutaminezuur gaat naar reactor R1 (met CO₂ als afsplitsingsproduct), via scheidingsruimte S1 (met afvalstroom) naar reactor R2, via scheidingsruimte S2 (met afvalstroom) naar reactor R3, en ten slotte naar scheidingsruimte S3 (met afvalstroom). Bij een aantal pijlen tussen de stappen ontbreken nog de stofnamen (aangeduid met *).$$, 'uitwerkbijlage');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('2d675646-45f3-422c-b037-c5f6d8a9618d', '53e914fe-87af-462a-b836-9deeec047e81', 1,
   '[{"domain": "Reacties", "subdomain": "Chemische processen"}]'::jsonb,
   '["fenylalanine", "kaneelzuur", "enzym", "reactievergelijking", "eliminatiereactie"]'::jsonb,
   $$Bepalen van het bij PAL vrijkomende deeltje (NH₃) bij de omzetting van fenylalanine tot kaneelzuur$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-pal-vraag1.png$$, $$1p 1 Geef de formule van het ontbrekende deeltje.$$, array['fcdac3f1-ca44-4bce-a16b-8e07666447cf']::uuid[]),
  ('8b56be4c-df6c-49f8-b7cd-fc15de7aa02e', '53e914fe-87af-462a-b836-9deeec047e81', 2,
   '[{"domain": "Chemie van het leven", "subdomain": "Structuur en functie"}, {"domain": "Reacties", "subdomain": "Chemische processen"}]'::jsonb,
   '["tripeptide", "aminozuur", "ringsluiting", "additiereactie", "structuurformule", "watermolecuul"]'::jsonb,
   $$Structuurformule van het tripeptide Ala-Ser-Gly en de ringsluitingsreactie tot de MIO-groep$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-pal-vraag2.png$$, $$4p 2 Geef de structuurformule van het gedeelte ~Ala–Ser–Gly~. Geef in de structuurformule met een pijl/pijlen aan welke twee atomen met elkaar worden verbonden bij de ringsluiting. Omcirkel in de structuurformule de H-atomen en de O-atomen die bij de vorming van de MIO-groep worden afgesplitst.$$, array['f4cfb3af-8511-476d-a447-2f268370b179']::uuid[]),
  ('7d93997a-2176-4824-9d9d-53ffd025f592', '53e914fe-87af-462a-b836-9deeec047e81', 3,
   '[{"domain": "Chemie van het leven", "subdomain": "Reactiviteit en selectiviteit"}]'::jsonb,
   '["fenylalanine", "tyrosine", "functionele groep", "enzymactiviteit", "actieve plaats"]'::jsonb,
   $$Vergelijken van de aminozuren fenylalanine (Phe) en tyrosine (Tyr) als verklaring voor het verlies van enzymactiviteit$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-pal-vraag3.png$$, $$2p 3 Geef twee chemische redenen waarom Phe is gekozen als vervanger van Tyr110. Licht je antwoord toe, zodat duidelijk wordt waarom dit voor het onderzoek relevante redenen zijn.$$, array['58ade700-904a-4119-95cb-2a3a8e81ab3b']::uuid[]),
  ('5cb86c64-4a38-41ca-98c2-ce3bfe86f3e6', '53e914fe-87af-462a-b836-9deeec047e81', 4,
   '[{"domain": "Chemie van het leven", "subdomain": "Structuur en functie"}]'::jsonb,
   '["puntmutatie", "DNA", "basenpaar", "coderende streng", "matrijsstreng", "genetische code", "Binas-tabel"]'::jsonb,
   $$Bepalen van de basenparen die coderen voor Tyr110 en Phe110 met behulp van de genetische code$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-pal-vraag4.png$$, $$3p 4 Geef de symbolen van het basenpaar van de puntmutatie, zowel voor de actieve PAL met Tyr110 als voor de inactieve PAL met Phe110. Gebruik Binas-tabel 71G. Noteer je antwoord als volgt en licht je antwoord toe: [tabel met kolommen actieve PAL / inactieve PAL en rijen: base op coderende streng: ..... / .....; base op matrijsstreng: ..... / .....] Toelichting: .....$$, array['7ef6d1ad-8cbf-4aa1-b273-e0686dffb552']::uuid[]),
  ('cff2e6be-9623-4a45-8894-53bece41f3f0', '53e914fe-87af-462a-b836-9deeec047e81', 5,
   '[{"domain": "Chemie van het leven", "subdomain": "Structuur en functie"}]'::jsonb,
   '["puntmutatie", "DNA", "basenpaar", "aminozuurvolgorde", "genetische code"]'::jsonb,
   $$Bepalen van het volgnummer van het gemuteerde basenpaar in het PAL-gen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-pal-vraag5.png$$, $$2p 5 Geef aan wat het nummer is van het basenpaar van de puntmutatie. Licht je antwoord toe.$$, array['7ef6d1ad-8cbf-4aa1-b273-e0686dffb552']::uuid[]),
  ('70955d00-f1ee-48d9-975b-eea6e6b94be2', '53e914fe-87af-462a-b836-9deeec047e81', 6,
   '[{"domain": "Reacties", "subdomain": "Chemisch evenwicht"}, {"domain": "Rekenen en analyse", "subdomain": "Grootheden en relaties"}]'::jsonb,
   '["fenylalanine", "Kz", "pH-berekening", "zuur-baseevenwicht", "protonering"]'::jsonb,
   $$Berekenen van het percentage geprotoneerde aminogroepen van fenylalanine met behulp van de zuurconstante Kz$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-pal-vraag6.png$$, $$4p 6 Bereken hoeveel procent van de aminogroepen van fenylalanine aanwezig is als ~NH₃⁺ bij pH = 8,80 (T = 298 K).$$, array['f6f3a32e-d8d1-4fb0-9937-178c66bc444b']::uuid[]),
  ('54304af0-0267-409b-ab3d-4c22e243c52d', '53e914fe-87af-462a-b836-9deeec047e81', 7,
   '[{"domain": "Materie", "subdomain": "Bindingen en eigenschappen"}]'::jsonb,
   '["elektrostatische interactie", "Tyr110", "actieve centrum", "lading", "ion-dipoolbinding"]'::jsonb,
   $$Verklaren van de elektrostatische interacties tussen fenylalanine en Tyr110 die de oriëntatie bij het actieve centrum bepalen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-pal-vraag7.png$$, $$2p 7 Leg uit welke twee elektrostatische interacties tussen een fenylalanine-deeltje en het Tyr110 ervoor zorgdragen, dat een fenylalanine-deeltje de holte binnengaat op de manier zoals is weergegeven in figuur 3. Geef ook aan welke atoomgroep van het fenylalanine-deeltje betrokken is bij elke afzonderlijke interactie.$$, array['f0a4fafe-9a5b-4b46-a409-06978a6838bb']::uuid[]),
  ('03ee53cf-e5ff-4881-8d8f-40222ad91f61', '53e914fe-87af-462a-b836-9deeec047e81', 8,
   '[{"domain": "Reacties", "subdomain": "Reactiesnelheid en katalyse"}, {"domain": "Rekenen en analyse", "subdomain": "Grootheden en relaties"}]'::jsonb,
   '["turnover frequency", "enzym", "katalyse", "molaire massa", "kaneelzuur", "omzettingssnelheid"]'::jsonb,
   $$Berekenen van de turnover frequency (TOF) van het enzym PAL$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-pal-vraag8.png$$, $$3p 8 Bereken de TOF van PAL. De molaire massa van PAL bedraagt 2,75·10⁵ g mol⁻¹.$$, array['1b631491-fa6c-4eaf-9c4a-96e56ede7b0f']::uuid[]),
  ('347c9c50-fc05-4f95-8a46-7782b317c010', '8db2ac27-404b-4a57-a618-2743bddb5d43', 9,
   '[{"domain": "Reacties", "subdomain": "Energie"}, {"domain": "Rekenen en analyse", "subdomain": "Grootheden en relaties"}]'::jsonb,
   '["waterstof", "verbrandingswarmte", "energie-inhoud", "brandstof", "molair volume"]'::jsonb,
   $$Berekenen van de benodigde massa waterstof voor eenzelfde actieradius als een tank benzine$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-waterstofopslag-in-carbazool-vraag9.png$$, $$3p 9 Bereken hoeveel kilogram waterstof een auto moet tanken om dezelfde afstand af te leggen als een benzineauto met een tank gevuld met 50 liter benzine (T = 298 K, p = p₀). Bij beide verbrandingen komt het water als gas vrij. Bij de verbranding van 1,0 m³ benzine komt 3,3·10¹⁰ J vrij.$$, array['f88fa8fd-e9b1-4c37-bafd-ef5556e8ffe6']::uuid[]),
  ('baa10d86-3057-46eb-808d-e4c70b040375', '8db2ac27-404b-4a57-a618-2743bddb5d43', 10,
   '[{"domain": "Rekenen en analyse", "subdomain": "Grootheden en relaties"}, {"domain": "Reacties", "subdomain": "Chemische processen"}]'::jsonb,
   '["N-ethylcarbazool", "additiereactie", "massaverhouding", "waterstofdrager", "molecuulformule"]'::jsonb,
   $$Berekenen van de massatoename van N-ethylcarbazool bij volledige additie van waterstof$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-waterstofopslag-in-carbazool-vraag10.png$$, $$2p 10 Bereken met welk percentage van zijn oorspronkelijke massa de massa van N-ethylcarbazool toeneemt als alle dubbele bindingen in N-ethylcarbazool worden omgezet tot enkelvoudige bindingen. Geef je antwoord in twee significante cijfers.$$, array['f4b46d3c-316f-4b6b-811f-5a28bcc553db']::uuid[]),
  ('a5c26aff-4b91-40b5-a190-7d6898cadbbd', '8db2ac27-404b-4a57-a618-2743bddb5d43', 11,
   '[{"domain": "Reacties", "subdomain": "Reactiekinetiek"}]'::jsonb,
   '["reactieverloop", "concentratie-tijddiagram", "omzetting", "tussenproduct"]'::jsonb,
   $$Beoordelen aan de hand van concentratie-tijddiagrammen of de omzetting tot perhydro-N-ethylcarbazool compleet is$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-waterstofopslag-in-carbazool-vraag11.png$$, $$2p 11 Leg aan de hand van de diagrammen in figuur 1 uit of na 400 minuten een volledige omzetting tot perhydro-N-ethylcarbazool is bereikt.$$, array['f5b5e6f1-2272-4b6d-abb1-a7b092a258d0']::uuid[]),
  ('b87fcb41-65f9-402a-893a-1ef896e9d915', '8db2ac27-404b-4a57-a618-2743bddb5d43', 12,
   '[{"domain": "Reacties", "subdomain": "Reactiekinetiek"}]'::jsonb,
   '["snelheidsbepalende stap", "reactiemechanisme", "tussenproduct", "concentratie-tijddiagram"]'::jsonb,
   $$Bepalen van de snelheidsbepalende stap in de omzetting van N-ethylcarbazool tot perhydro-N-ethylcarbazool$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-waterstofopslag-in-carbazool-vraag12.png$$, $$Uit de diagrammen kan worden opgemaakt welke van de vijf weergegeven omzettingen de snelheidsbepalende stap is voor de omzetting van N-ethylcarbazool tot perhydro-N-ethylcarbazool. 2p 12 Leg aan de hand van de diagrammen in figuur 1 uit welke omzetting de snelheidsbepalende stap is.$$, array['f5b5e6f1-2272-4b6d-abb1-a7b092a258d0']::uuid[]),
  ('fc7a2ebc-3aa2-4ae0-b177-f633f305053a', '8db2ac27-404b-4a57-a618-2743bddb5d43', 13,
   '[{"domain": "Technologie en duurzaamheid", "subdomain": "Milieu en gezondheid"}]'::jsonb,
   '["waterstofdrager", "explosiegevaar", "katalysator", "endotherme reactie", "veiligheid"]'::jsonb,
   $$Verklaren waarom opslag van waterstof als perhydro-N-ethylcarbazool het explosierisico verkleint$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-waterstofopslag-in-carbazool-vraag13.png$$, $$2p 13 Leg uit dat bij opslag en vervoer van perhydro-N-ethylcarbazool het risico op een explosie van waterstof erg klein is. Gebruik bij de beantwoording van deze vraag drie gegevens uit bovenstaande tekst.$$, array['4729b8b6-505d-4039-bd6a-56e906526e5c']::uuid[]),
  ('46b25fa6-81c6-4947-9432-38a22b9b2bdf', '8db2ac27-404b-4a57-a618-2743bddb5d43', 14,
   '[{"domain": "Reacties", "subdomain": "Energie"}]'::jsonb,
   '["energiediagram", "katalysator", "activeringsenergie", "endotherme reactie", "uitwerkbijlage"]'::jsonb,
   $$Aanvullen van het energiediagram voor de waterstofvorming uit perhydro-N-ethylcarbazool met en zonder katalysator$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-waterstofopslag-in-carbazool-vraag14.png$$, $$Op de uitwerkbijlage bij dit examen is het energiediagram voor de vorming van waterstof uit perhydro-N-ethylcarbazool onvolledig weergegeven. Hierin ontbreekt onder andere het niveau van de reactieproducten. De invloed van de katalysator op het verloop van deze reactie kan met behulp van dit energiediagram duidelijk worden gemaakt door energieniveaus met bijbehorende bijschriften te plaatsen. 2p 14 Maak op de uitwerkbijlage het energiediagram voor de vorming van waterstof uit perhydro-N-ethylcarbazool af door energieniveaus met bijbehorende bijschriften te plaatsen, zodat duidelijk wordt wat de invloed van de katalysator is op het verloop van de reactie.$$, array['d14e32c7-6a42-4744-97a4-fe5f484be13f']::uuid[]),
  ('4aed992e-9abf-4ab0-8c84-2c76229a6967', '7cddafe7-58c1-4630-9bb6-791a00ce2761', 15,
   '[{"domain": "Reacties", "subdomain": "Chemische processen"}]'::jsonb,
   '["BOC-4-hydroxystyreen", "di-tert-butyldicarbonaat", "condensatiereactie", "structuurformule", "esterificatie"]'::jsonb,
   $$Structuurformulevergelijking van de vorming van BOC-4-hydroxystyreen uit 4-hydroxystyreen en di-tert-butyldicarbonaat$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-polymeren-maken-de-chip-vraag15.png$$, $$2p 15 Maak de vergelijking op de uitwerkbijlage compleet. Gebruik structuurformules.$$, array['3c320be1-f4be-4a99-a8d1-ac249968f30e','7522c76f-346e-4bdd-a7be-b6e043049fab']::uuid[]),
  ('eb41ec7e-a5c9-466d-a6c7-9c552be23dad', '7cddafe7-58c1-4630-9bb6-791a00ce2761', 16,
   '[{"domain": "Reacties", "subdomain": "Chemische processen"}]'::jsonb,
   '["BOC-4-hydroxystyreen", "methylpropeen", "koolstofdioxide", "katalyse", "structuurformule"]'::jsonb,
   $$Structuurformulevergelijking van de H⁺-gekatalyseerde omzetting van een BOC-4-hydroxystyreen-eenheid tot 4-hydroxystyreen, methylpropeen en CO₂$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-polymeren-maken-de-chip-vraag16.png$$, $$3p 16 Geef de vergelijking in structuurformules van de omzetting van één BOC-4-hydroxystyreen-eenheid uit copolymeer X tot één 4-hydroxystyreen-eenheid.$$, array['3c320be1-f4be-4a99-a8d1-ac249968f30e','9610346d-1067-4a07-91c7-aea1fd0adeae']::uuid[]),
  ('2a35127f-1386-4846-9825-2356309e3e29', '7cddafe7-58c1-4630-9bb6-791a00ce2761', 17,
   '[{"domain": "Reacties", "subdomain": "Reactiesnelheid en katalyse"}]'::jsonb,
   '["PAG", "katalysator", "molverhouding", "fotogevoelige laag"]'::jsonb,
   $$Beredeneren van de molverhouding tussen PAG en BOC-4-hydroxystyreen-eenheden op basis van de katalytische werking van H⁺$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-polymeren-maken-de-chip-vraag17.png$$, $$2p 17 Leg uit of je verwacht of de molverhouding PAG/BOC-4-hydroxystyreen-eenheden in de fotogevoelige laag groter is dan 1, kleiner is dan 1 of gelijk is aan 1.$$, array['9610346d-1067-4a07-91c7-aea1fd0adeae']::uuid[]),
  ('807ee948-6754-4fd0-b675-037e915d028e', '7cddafe7-58c1-4630-9bb6-791a00ce2761', 18,
   '[{"domain": "Materie", "subdomain": "Bindingen en eigenschappen"}]'::jsonb,
   '["poly-4-hydroxystyreen", "oplosbaarheid", "deprotonering", "ion-dipoolbinding", "basische oplossing"]'::jsonb,
   $$Verklaren op microniveau waarom gedeprotoneerd poly-4-hydroxystyreen goed oplost in een basische oplossing$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-i-polymeren-maken-de-chip-vraag18.png$$, $$2p 18 Geef een verklaring op microniveau voor het gegeven dat poly-4-hydroxystyreen dan goed oplost.$$, array['91322406-7b27-4b53-b5e3-3b929fc13b8d']::uuid[]),
  ('69794662-cdf0-48f5-ba84-292f512bd91b', '7cddafe7-58c1-4630-9bb6-791a00ce2761', 19,
